# 12_tables.R: summary tables for the replacement-oriented components (tables_repl/)
source("lib6.R"); dir.create("tables_repl", FALSE); V <- readRDS("out/repl_validation.rds"); I <- readRDS("out/repl_importance.rds")
cat("non-converged fits:", sum(!V$converged), "of", nrow(V), "\n")
vf <- V |> group_by(group, order, component, model, fold) |> summarise(D2 = mean(D2_heldout), mean_y = mean(mean_y), sd_y = mean(sd_y), .groups = "drop")
vs <- vf |> group_by(group, order, component, model) |> summarise(D2_median = median(D2), D2_min = min(D2), D2_max = max(D2), mean_dissimilarity = mean(mean_y), sd_dissimilarity = mean(sd_y), n_folds = n(), .groups = "drop"); write.csv(vs, "tables_repl/validation_summary.csv", row.names = FALSE)
g <- vf |> select(group, order, component, model, fold, D2) |> pivot_wider(names_from = model, values_from = D2) |> mutate(nonlinear_position = nonlinear_const - linear_const, interaction_default = nonlinear_varying - nonlinear_const, interaction_pen1e4 = `nonlinear_varying_pen1e-4` - nonlinear_const) |>
  group_by(group, order, component) |> summarise(across(c(nonlinear_position, interaction_default, interaction_pen1e4), list(med = median, lo = min, hi = max, pos = ~mean(. > 0))), .groups = "drop"); write.csv(g, "tables_repl/validation_gains.csv", row.names = FALSE)
# importance at predictor level (spread + position / distance), fold x seed means
P <- I |> group_by(group, order, comp, model, seed, fold, predictor) |> summarise(absolute = if (all(is.na(absolute))) NA_real_ else sum(absolute), relative = if (all(is.na(relative))) NA_real_ else sum(relative), D2 = first(D2_heldout), .groups = "drop")
PF <- P |> group_by(group, order, comp, model, fold, predictor) |> summarise(absolute = mean(absolute, na.rm = TRUE), relative = mean(relative, na.rm = TRUE), D2 = mean(D2), .groups = "drop") |> mutate(across(c(absolute, relative), ~ ifelse(is.nan(.), NA, .)))
imp <- PF |> group_by(group, order, comp, model, predictor) |> summarise(absolute_mean = mean(absolute, na.rm = TRUE), abs_lo = suppressWarnings(min(absolute, na.rm = TRUE)), abs_hi = suppressWarnings(max(absolute, na.rm = TRUE)), relative_mean = mean(relative, na.rm = TRUE), relative_valid_folds = sum(!is.na(relative)), n_valid = sum(!is.na(absolute)), heldout_D2 = mean(D2), .groups = "drop") |> mutate(across(c(absolute_mean, abs_lo, abs_hi, relative_mean), ~ ifelse(is.finite(.), ., NA)))
write.csv(imp, "tables_repl/importance_predictor.csv", row.names = FALSE)
tm <- I |> group_by(group, order, comp, model, predictor, component) |> summarise(absolute = mean(absolute, na.rm = TRUE), .groups = "drop"); write.csv(tm, "tables_repl/importance_terms.csv", row.names = FALSE)
cat("failed/NA absolute allocations:\n"); print(I |> filter(is.na(absolute)) |> count(group, comp, model))
# magnitude vs importance: correlation across orders within group x component of (mean dissimilarity, total D2, TP absolute, TP relative)
mi <- imp |> filter(model == "nonlinear_const", predictor == "TP") |> left_join(vs |> filter(model == "nonlinear_const") |> select(group, order, comp = component, mean_dissimilarity, sd_dissimilarity), by = c("group", "order", "comp"))
write.csv(mi, "tables_repl/magnitude_vs_tp_importance.csv", row.names = FALSE)
options(width = 220); cat("\nTP absolute / relative, additive nonlinear model\n"); print(mi |> select(group, comp, order, mean_dissimilarity, heldout_D2, absolute_mean, relative_mean) |> mutate(across(where(is.numeric), ~ round(., 3))) |> as.data.frame())
cat("\nInteraction gains\n"); print(g |> select(group, order, component, nonlinear_position_med, interaction_default_med, interaction_pen1e4_med) |> mutate(across(where(is.numeric), ~ signif(., 2))) |> as.data.frame())
